import{_ as d,o as r,c as a,ag as o}from"./chunks/framework.KxDd3USm.js";const C=JSON.parse('{"title":"09.5 I/O、总线与指令系统 ★★★","description":"","frontmatter":{},"headers":[],"relativePath":"09-计算机系统基础/05-IO总线与指令系统.md","filePath":"09-计算机系统基础/05-IO总线与指令系统.md"}'),e={name:"09-计算机系统基础/05-IO总线与指令系统.md"};function i(l,t,n,s,h,c){return r(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="_09-5-i-o、总线与指令系统-★★★" tabindex="-1">09.5 I/O、总线与指令系统 ★★★ <a class="header-anchor" href="#_09-5-i-o、总线与指令系统-★★★" aria-label="Permalink to &quot;09.5 I/O、总线与指令系统 ★★★&quot;">​</a></h1><h3 id="_7-1-cpu-怎样与外设交换数据" tabindex="-1">7.1 CPU 怎样与外设交换数据 <a class="header-anchor" href="#_7-1-cpu-怎样与外设交换数据" aria-label="Permalink to &quot;7.1 CPU 怎样与外设交换数据&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方式</th><th>谁盯设备</th><th>CPU 负担</th><th>适用特点</th></tr></thead><tbody><tr><td>程序查询</td><td>CPU 反复查询</td><td>最大，忙等</td><td>简单、低速</td></tr><tr><td>中断</td><td>设备就绪后通知 CPU</td><td>不必忙等，但每次传送仍需 CPU 处理</td><td>低中速、事件驱动</td></tr><tr><td>DMA</td><td>DMA 控制器在主存与外设间成批传送</td><td>很小，CPU 只做初始化与结束处理</td><td>高速、批量</td></tr><tr><td>通道/I/O 处理机</td><td>专用部件执行 I/O 程序</td><td>更小</td><td>大型系统、多设备</td></tr></tbody></table><p>DMA 的关键不是“完全不经过主存”，恰好相反，它让<strong>外设与主存直接成批交换数据</strong>，只是在传送期间暂时取得总线控制权，减少 CPU 逐字搬运。</p><h3 id="_7-2-中断过程" tabindex="-1">7.2 中断过程 <a class="header-anchor" href="#_7-2-中断过程" aria-label="Permalink to &quot;7.2 中断过程&quot;">​</a></h3><p>简化顺序：</p><ol><li>设备发出中断请求；</li><li>CPU 通常在当前指令执行完后响应；</li><li>保存断点和现场；</li><li>根据<strong>中断向量</strong>找到中断服务程序入口；</li><li>执行中断服务程序；</li><li>恢复现场，返回原程序。</li></ol><p><strong>中断向量 = 中断服务程序的入口地址（或形成入口地址的信息）</strong>。断点是原程序被打断后应继续执行的位置，二者不是一回事。</p><h3 id="_7-3-总线分类" tabindex="-1">7.3 总线分类 <a class="header-anchor" href="#_7-3-总线分类" aria-label="Permalink to &quot;7.3 总线分类&quot;">​</a></h3><p>按传送内容：</p><ul><li>数据总线：传数据，通常双向；</li><li>地址总线：传地址，通常由 CPU 向外，宽度决定可寻址空间；</li><li>控制总线：传读/写、中断、总线请求等控制信号。</li></ul><p>若地址总线有 32 根，按字节编址，可寻址单元数为 2^32，空间为 2^32 B = <strong>4 GiB</strong>。</p><p>按范围可分芯片内总线、系统总线、外部/通信总线；按传送方式可分串行和并行。并行不是永远更快：线路较长、频率较高时，多根线的时序偏差和串扰会限制速度，现代高速外设常用高速串行链路。</p><p><strong>应试动作</strong>：题干出现“CPU 忙等”选查询，“设备通知 CPU”选中断，“主存与高速外设批量直传”选 DMA。“中断服务入口”选中断向量；地址线 n 根、按字节编址就写 2^n B。</p><hr><h2 id="第八节-指令、寻址方式与-risc-cisc-★★★" tabindex="-1">第八节 指令、寻址方式与 RISC/CISC ★★★ <a class="header-anchor" href="#第八节-指令、寻址方式与-risc-cisc-★★★" aria-label="Permalink to &quot;第八节 指令、寻址方式与 RISC/CISC ★★★&quot;">​</a></h2><h3 id="_8-1-寻址方式-指令里的地址字段究竟装了什么" tabindex="-1">8.1 寻址方式：指令里的地址字段究竟装了什么 <a class="header-anchor" href="#_8-1-寻址方式-指令里的地址字段究竟装了什么" aria-label="Permalink to &quot;8.1 寻址方式：指令里的地址字段究竟装了什么&quot;">​</a></h3><p>设指令地址字段为 A，寄存器 R 的内容记为 (R)，主存单元 A 的内容记为 (A)，EA 为有效地址。</p><table tabindex="0"><thead><tr><th>寻址方式</th><th>操作数/有效地址</th><th>一句话识别</th></tr></thead><tbody><tr><td>立即寻址</td><td>操作数 = A</td><td>指令里就是数</td></tr><tr><td>直接寻址</td><td>EA=A，操作数=(A)</td><td>指令里是一次地址</td></tr><tr><td>间接寻址</td><td>EA=(A)，操作数=((A))</td><td>先从内存取地址，再取数</td></tr><tr><td>寄存器寻址</td><td>操作数=(R)</td><td>寄存器里就是数</td></tr><tr><td>寄存器间接寻址</td><td>EA=(R)，操作数=((R))</td><td>寄存器里是地址</td></tr><tr><td>相对寻址</td><td>EA=(PC)+A</td><td>相对当前程序位置</td></tr><tr><td>基址寻址</td><td>EA=(基址寄存器)+A</td><td>基地址加偏移</td></tr><tr><td>变址寻址</td><td>EA=A+(变址寄存器)</td><td>数组首址加下标</td></tr></tbody></table><p>例：A=100，(100)=500，(500)=36：</p><ul><li>立即寻址得到 100；</li><li>直接寻址得到 500；</li><li>间接寻址得到 36。</li></ul><p><strong>反例</strong>：直接寻址不是“直接拿到操作数”，而是直接拿到操作数的地址；真正把操作数写在指令中的是立即寻址。寄存器间接寻址也不是操作数在寄存器，而是操作数的地址在寄存器。</p><h4 id="有效地址算例-相对、基址、变址别混" tabindex="-1">有效地址算例：相对、基址、变址别混 <a class="header-anchor" href="#有效地址算例-相对、基址、变址别混" aria-label="Permalink to &quot;有效地址算例：相对、基址、变址别混&quot;">​</a></h4><ul><li><strong>相对寻址</strong>：若 <code>(PC)=1000</code>，地址字段 <code>A=40</code>，则 <code>EA=1000+40=1040</code>。程序整体搬家后 PC 随之改变，位移 40 不变，适合分支与位置无关代码。</li><li><strong>基址寻址</strong>：若基址寄存器内容为 2000，位移 <code>A=120</code>，则 <code>EA=2000+120=2120</code>。基址常由系统设置，便于程序或存储区域重定位。</li><li><strong>变址寻址</strong>：若数组首址 <code>A=5000</code>，变址寄存器内容为 12，则 <code>EA=5000+12=5012</code>。变址值常随循环变化，适合访问数组元素。</li></ul><p>三者表面都是“加法”，区别在谁是稳定基准、谁会变化：<strong>相对看 PC，基址看程序/区域起点，变址看数组下标或偏移</strong>。</p><p>考试默认速度排序通常写：</p><blockquote><p><strong>立即寻址 ＞ 寄存器寻址 ＞ 直接寻址 ＞ 间接寻址</strong></p></blockquote><p>这里“＞”表示通常更快。立即数已随指令取入，寄存器寻址只访问寄存器；直接寻址要额外访问一次主存取操作数；间接寻址通常先去主存取有效地址，再去主存取操作数，额外访存最多。若题面明确给出某体系结构的周期数，应按题面数据计算。</p><h3 id="_8-2-risc-与-cisc" tabindex="-1">8.2 RISC 与 CISC <a class="header-anchor" href="#_8-2-risc-与-cisc" aria-label="Permalink to &quot;8.2 RISC 与 CISC&quot;">​</a></h3><table tabindex="0"><thead><tr><th>对比</th><th>RISC（精简指令集）</th><th>CISC（复杂指令集）</th></tr></thead><tbody><tr><td>指令数量与格式</td><td>少、格式较规整/常定长</td><td>多、常变长</td></tr><tr><td>寻址方式</td><td>少</td><td>多</td></tr><tr><td>单条指令</td><td>功能较简单，多数可快速完成</td><td>功能复杂，周期差异大</td></tr><tr><td>访存</td><td><strong>Load/Store</strong>：通常只有装入/存储指令访问内存</td><td>多种指令可直接访问内存</td></tr><tr><td>寄存器</td><td>通用寄存器多</td><td>相对较少</td></tr><tr><td>控制实现</td><td>常用硬布线，利于流水线</td><td>常用微程序控制</td></tr><tr><td>编译器</td><td>更依赖优化编译</td><td>指令本身表达力强</td></tr></tbody></table><p><strong>反例</strong>：“RISC 指令少，所以程序一定更短”是错的。完成同一复杂任务，RISC 可能需要更多条简单指令；它追求的是规则、快速、易流水化，不是源程序或机器码条数必然更少。</p><p><strong>流水线辨析</strong>：CISC 并非“绝对不能使用流水线”，现代 CISC 处理器同样会采用流水、译码和内部微操作等技术；只是 RISC 的定长、规整指令和较少寻址方式让分段更均匀，<strong>更容易高效流水化</strong>。因此题目问“更适合流水线”选 RISC，问“能否使用流水线”时不能断言 CISC 完全不能。</p><p>口诀：<strong>RISC：少、齐、快，多寄存器，Load/Store，硬布线，爱流水；CISC 反过来。</strong></p><p><strong>应试动作</strong>：题干出现“定长、少寻址、多寄存器、Load/Store、硬布线、易于流水”就锁定 RISC；“复杂指令、多寻址、可变长、微程序”锁定 CISC。注意“更适合流水线”不等于“另一类绝对不能流水”。</p><hr>',35)])])}const _=d(e,[["render",i]]);export{C as __pageData,_ as default};
